import{_ as t}from"./chunks/constraints_strandbeest.D_ZibCgJ.js";import{_ as s,o as a,c as o,a5 as r}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Server Example: Strandbeest Closed Loops","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/strandbeest_closed_loops.md","filePath":"sections/examples/server/strandbeest_closed_loops.md"}'),l={name:"sections/examples/server/strandbeest_closed_loops.md"};function n(i,e,d,c,p,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="server-example-strandbeest-closed-loops" tabindex="-1">Server Example: Strandbeest Closed Loops <a class="header-anchor" href="#server-example-strandbeest-closed-loops" aria-label="Permalink to &quot;Server Example: Strandbeest Closed Loops&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A 12-legged Strandbeest walks, driven by one crank. Its 36 closed kinematic loops are closed by URDF <code>&lt;equality&gt;</code> constraints (see <a href="./../../articulated_system/ClosedLoopSystems.html">Closed-Loop Systems</a>).</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><img src="'+t+'" alt="strandbeest_closed_loops example" style="width:70%;"><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>strandbeest_closed_loops</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/strandbeest_closed_loops</span></span></code></pre></div><p>On Windows, run <code>strandbeest_closed_loops.exe</code> instead. This example uses RaisimServer. Start <code>rayrai_tcp_viewer</code> and connect to port 8080.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads <code>rsc/strandbeest/strandbeest.urdf</code>, converted from the MIT-licensed <a href="https://github.com/rdeits/StrandbeestRobot.jl" target="_blank" rel="noreferrer">StrandbeestRobot.jl</a> model: 79 degrees of freedom and 36 loop constraints.</li><li>Every loop is planar, so each loop hinge is an equality constraint along the two axes normal to its hinge axis. Closing them with two pins per hinge instead gives the same motion, but doubles the number of constraint rows (half of them redundant) and made a step about 3.5 times slower.</li><li>The constraints are eliminated exactly every step, so the contact solver only iterates on the feet&#39;s ground contacts (about two sweeps per step).</li><li>The crank <code>joint_crossbar_crank</code> turns at one revolution per second through a velocity-only PD; every other joint is passive. The Strandbeest walks about 1.3 m per crank revolution.</li></ul>',13)])])}const _=s(l,[["render",n]]);export{u as __pageData,_ as default};
